// GitHub Pages serves the fields generated by scripts/export_pages.py.
// The browser samples published fields and integrates trajectories in EPSG:3409.
import { ApiError } from './client.js'

const cache = new Map()
const DAY = 86400000
const HOUR = 3600000
const DEG = Math.PI / 180
const RADIUS = 6371228
const round = (value, digits) => Number(value.toFixed(digits))
const dateOnly = (date) => date.slice(0, 10)
const normalizeAngle = (degrees) => (degrees + 360) % 360
const modelAngle = (u, v) => normalizeAngle(Math.atan2(v, u) / DEG)
const distance = (hours, speed) => hours * speed * 0.036

async function json(file) {
  const response = await fetch(import.meta.env.BASE_URL + 'snapshots/' + file, { cache: 'no-cache' })
  if (!response.ok) throw new ApiError('公开预报数据加载失败', { status: response.status })
  return response.json()
}

function cached(file) {
  if (!cache.has(file)) {
    cache.set(file, json(file).catch(error => {
      cache.delete(file)
      throw error
    }))
  }
  return cache.get(file)
}

async function published(recent) {
  recent ??= await cached('recent.json')
  if (!recent.available || !/^fields-\d{4}-\d{2}-\d{2}\.json$/.test(recent.fields_file)) {
    throw new ApiError('当前没有已发布的预报批次')
  }
  const fields = await cached(recent.fields_file + '?batch=' + encodeURIComponent(recent.published_at))
  if (fields.date !== recent.latest_date) throw new ApiError('预报批次正在更新，请刷新页面')
  return { fields, recent }
}

function fieldPayload({ fields, recent }, model, days) {
  const { grid, observed, forecasts, lat, lon } = fields
  const field = model ? forecasts[model][days - 1] : observed
  const row_axis = field.map((_, row) => row)
  const col_axis = field[0].map((_, col) => col)
  const stride = 5
  const vectors = { stride, rows: [], cols: [], u: [], v: [], speed: [] }
  let sum = 0
  let max = 0
  let count = 0
  const speed = field.map((line, row) => line.map((pair, col) => {
    if (!pair) return null
    const [u, v] = pair
    const magnitude = Math.hypot(u, v)
    max = Math.max(max, magnitude)
    sum += magnitude
    count++
    if (row % stride === 0 && col % stride === 0) {
      vectors.rows.push(row)
      vectors.cols.push(col)
      vectors.u.push(round(u, 2))
      vectors.v.push(round(v, 2))
      vectors.speed.push(round(magnitude, 2))
    }
    return round(magnitude, 2)
  }))
  const result = {
    kind: model ? 'predicted' : 'observed', date: fields.date, grid, row_axis, col_axis,
    row_lat: row_axis.map(row => lat[row][Math.floor(grid.cols / 2)]),
    col_lon: col_axis.map(col => lon[Math.floor(grid.rows / 2)][col]),
    speed, vectors, warnings: [], source: recent.source,
    stats: {
      valid_cells: count, coverage: round(count / (grid.rows * grid.cols), 4),
      mean_speed: count ? round(sum / count, 2) : null, max_speed: count ? round(max, 2) : null,
    },
  }
  if (model) {
    result.model = { id: model }
    result.valid_at = new Date(Date.parse(recent.latest_at) + days * DAY).toISOString()
    result.target_date = dateOnly(result.valid_at)
  }
  return result
}

function bearing(lat0, lon0, lat1, lon1) {
  const a = lat0 * DEG
  const b = lat1 * DEG
  const delta = (lon1 - lon0) * DEG
  return normalizeAngle(Math.atan2(
    Math.sin(delta) * Math.cos(b),
    Math.cos(a) * Math.sin(b) - Math.sin(a) * Math.cos(b) * Math.cos(delta),
  ) / DEG)
}

function integrate(fields, forecasts, row, col, days, end) {
  const latitude = fields.lat[row][col] * DEG
  const longitude = fields.lon[row][col] * DEG
  const rho = 2 * RADIUS * Math.sin((Math.PI / 2 + latitude) / 2)
  let x = rho * Math.sin(longitude)
  let y = rho * Math.cos(longitude)
  let nextRow = row
  let nextCol = col
  let km = 0
  const path = {
    hours: [], cumulative_km: [], speed_cm_s: [], row: [], col: [], lat: [], lon: [],
    uncertainty: null, interpolation: '按各日预测矢量分段积分。逐时位置为估计值。',
  }
  const append = (speed) => {
    path.hours.push(path.hours.length)
    path.cumulative_km.push(round(km, 3))
    path.speed_cm_s.push(round(speed, 3))
    path.row.push(round(nextRow, 5))
    path.col.push(round(nextCol, 5))
    path.lat.push(round((2 * Math.asin(Math.hypot(x, y) / (2 * RADIUS)) - Math.PI / 2) / DEG, 7))
    path.lon.push(round(Math.atan2(x, y) / DEG, 7))
  }
  for (const field of forecasts.slice(0, days)) {
    const pair = field[Math.round(nextRow)]?.[Math.round(nextCol)]
    if (!pair) break
    const [u, v] = pair
    const speed = Math.hypot(u, v)
    if (!path.hours.length) append(speed)
    for (let hour = 0; hour < 24; hour++) {
      nextRow += distance(1, v) / fields.grid.cell_km
      nextCol += distance(1, u) / fields.grid.cell_km
      x += u * 36
      y += v * 36
      km += distance(1, speed)
      append(speed)
    }
  }
  const validAt = new Date(end + (path.hours.length - 1) * HOUR).toISOString()
  return { path: { ...path, target_date: dateOnly(validAt) }, validAt }
}

async function predict({ fields, recent }, payload) {
  const { cell: { row, col }, model, lead_days: days } = payload
  const forecasts = fields.forecasts[model]
  const observed = fields.observed[row]?.[col]
  if (!observed) throw new ApiError('该像元缺少近期海冰漂移观测，请选择图中有颜色的像元')
  const started = performance.now()
  const end = Date.parse(recent.latest_at)
  const { path, validAt } = integrate(fields, forecasts, row, col, days, end)
  const first = integrate(fields, forecasts, row, col, 1, end)
  const series_24h = first.path
  const [u, v] = forecasts[0][row][col]
  const [ou, ov] = observed
  const speed = Math.hypot(u, v)
  const obsSpeed = Math.hypot(ou, ov)
  const metadata = await cached('models.json')
  const selected = metadata.models.find(item => item.id === model)
  const stillValid = Date.parse(validAt) > Date.now()
  const warnings = [{
    code: 'recent_product_shift', level: 'info',
    message: 'OSI SAF 的 62.5 km、48h 平均漂移已转换到训练网格。历史 NSIDC 测试指标不适用于此数据源。',
  }]
  if (days > 1) warnings.push({
    code: 'multi_day_experimental', level: 'warning',
    message: '多日预报为试验性结果，误差可能随时效增加。',
  })
  if (path.hours.length < days * 24 + 1) warnings.unshift({
    code: 'path_outside_support', level: 'warning',
    message: '轨迹进入近期观测覆盖之外，已在有支持的最后一天结束。',
  })
  if (!stillValid) warnings.unshift({
    code: 'forecast_already_ended', level: 'warning',
    message: '此轨迹的有效期已结束。图中曲线为已发布批次的存档结果。',
  })
  return {
    status: 'ok', status_text: '已载入模型预报',
    elapsed_ms: round(performance.now() - started, 1),
    model: { id: selected.id, name: selected.name, category: selected.category },
    data_time: {
      last_obs_date: fields.date, last_obs_index: recent.n_frames - 1, latest_date: fields.date,
      next_frame_date: first.path.target_date, horizon_hours: days * 24, n_frames: recent.n_frames,
      target_observed: false, source: recent.source, observation_end_at: recent.latest_at,
      forecast_valid_until: validAt, extends_past_now: stillValid,
    },
    input: {
      row, col, lat: fields.lat[row][col], lon: fields.lon[row][col], date: fields.date,
      u: round(ou, 4), v: round(ov, 4), speed: round(obsSpeed, 4),
      direction_deg: modelAngle(ou, ov), valid: true,
      coverage: recent.valid_cells / (fields.grid.rows * fields.grid.cols),
    },
    prediction: {
      u: round(u, 4), v: round(v, 4), speed: round(speed, 4), direction_deg: modelAngle(u, v),
      bearing_deg: normalizeAngle(round(bearing(
        series_24h.lat[0], series_24h.lon[0], series_24h.lat[24], series_24h.lon[24],
      ), 2)),
      displacement_km_24h: round(distance(24, speed), 3),
      delta_speed_vs_persistence: round(speed - obsSpeed, 4),
    },
    series_24h, series_horizon: path, metrics: null, warnings,
    daily_forecasts: forecasts.slice(0, days).map((field, index) => {
      const [dayU, dayV] = field[row][col]
      return {
        lead_hours: (index + 1) * 24,
        valid_at: new Date(end + (index + 1) * DAY).toISOString(),
        u: round(dayU, 4), v: round(dayV, 4), speed: round(Math.hypot(dayU, dayV), 4),
      }
    }),
  }
}

export async function handlePages(path, body) {
  const [route, query] = path.split('?')
  const params = new URLSearchParams(query)
  if (route === '/api/health') {
    await cached('recent.json')
    return { status: 'ok' }
  }
  if (route === '/api/recent/refresh') {
    const latest = await json('recent.json')
    const previous = await cache.get('recent.json')
    // Verify the new data asset before switching during a Pages deployment.
    if (previous && Date.parse(latest.latest_at) < Date.parse(previous.latest_at)) return previous
    await published(latest)
    if (previous?.fields_file !== latest.fields_file && previous?.fields_file) {
      cache.delete(previous.fields_file + '?batch=' + encodeURIComponent(previous.published_at))
    }
    cache.set('recent.json', Promise.resolve(latest))
    return latest
  }
  if (['/api/recent', '/api/models', '/api/metrics', '/api/overview'].includes(route)) {
    return cached(route.slice(5) + '.json')
  }
  if (route === '/api/backtest') return (await cached('backtest.json'))[body.model]
  const source = await published()
  const model = body?.model || params.get('model')
  const days = Number(body?.lead_days ?? params.get('lead_days') ?? 1)
  if ((model && !source.fields.forecasts[model]) || ![1, 2, 3].includes(days)) {
    throw new ApiError('此模型或时效不在已发布批次中')
  }
  if (route === '/api/recent/field') return fieldPayload(source, model, days)
  if (route === '/api/predict') return predict(source, body)
  throw new ApiError('请使用 GitHub Releases 安装版查看完整历史回测')
}
